      'নানা গম্ভীর হয়ে বললেন, "হ্যাঁ, মূসা (আ.) নিজেই। তূর পাহাড়ে আল্লাহর সাথে সরাসরি কথা বলার পর তিনি অনুরোধ করেছিলেন, হে আমার রব, আমাকে দেখাও, আমি তোমাকে দেখতে চাই।"',
